package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu   sync.Mutex
	now  time.Time
}

func newFakeClock(start time.Time) *fakeClock { return &fakeClock{now: start} }

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.now = c.now.Add(d)
}

func TestNewValidation(t *testing.T) {
	tests := []struct {
		name    string
		rate    float64
		burst   float64
		wantErr bool
	}{
		{"valid", 10, 5, false},
		{"zero rate", 0, 5, true},
		{"negative rate", -1, 5, true},
		{"zero burst", 10, 0, true},
		{"negative burst", 10, -1, true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := New(tc.rate, tc.burst, nil)
			if (err != nil) != tc.wantErr {
				t.Fatalf("New(%v, %v) err = %v, wantErr %v", tc.rate, tc.burst, err, tc.wantErr)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)

	tests := []struct {
		name     string
		rate     float64
		burst    float64
		actions  []func(*fakeClock) // advance clock, then attempt
		attempts []float64          // n values per action, in order
		want     []bool
	}{
		{
			name:  "burst exhausted",
			rate:  1, burst: 3,
			actions:  []func(*fakeClock){func(c *fakeClock) {}},
			attempts: []float64{4},
			want:     []bool{false},
		},
		{
			name:  "consume within burst",
			rate:  1, burst: 3,
			actions:  []func(*fakeClock){func(c *fakeClock) {}},
			attempts: []float64{3},
			want:     []bool{true},
		},
		{
			name: "refill over time",
			rate: 2, burst: 2,
			actions: []func(*fakeClock){
				func(c *fakeClock) { c.Advance(500 * time.Millisecond) }, // +1 token
				func(c *fakeClock) { c.Advance(500 * time.Millisecond) }, // +1 token
			},
			attempts: []float64{1, 1},
			want:     []bool{true, true},
		},
		{
			name: "insufficient refill",
			rate: 1, burst: 1,
			actions: []func(*fakeClock){
				func(c *fakeClock) { c.Advance(100 * time.Millisecond) }, // +0.1
			},
			attempts: []float64{1},
			want:     []bool{false},
		},
		{
			name: "cap at burst",
			rate: 10, burst: 2,
			actions: []func(*fakeClock){
				func(c *fakeClock) { c.Advance(10 * time.Second) }, // would be 100, capped at 2
			},
			attempts: []float64{2},
			want:     []bool{true},
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			clock := newFakeClock(base)
			l, err := New(tc.rate, tc.burst, clock)
			if err != nil {
				t.Fatalf("New: %v", err)
			}
			for i, act := range tc.actions {
				act(clock)
				if got := l.AllowN(tc.attempts[i]); got != tc.want[i] {
					t.Errorf("step %d: AllowN(%v) = %v, want %v", i, tc.attempts[i], got, tc.want[i])
				}
			}
		})
	}
}

func TestTokensRefillAndCap(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	l, _ := New(1, 5, clock)
	l.AllowN(5) // empty the bucket
	if got := l.Tokens(); got != 0 {
		t.Fatalf("after drain, tokens = %v, want 0", got)
	}
	clock.Advance(2 * time.Second)
	if got := l.Tokens(); got != 2 {
		t.Errorf("tokens = %v, want 2", got)
	}
	clock.Advance(100 * time.Second)
	if got := l.Tokens(); got != 5 {
		t.Errorf("tokens = %v, want capped 5", got)
	}
}

func TestConcurrentAccess(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	l, _ := New(1000, 100, clock)
	var wg sync.WaitGroup
	allowed := make([]bool, 200)
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			allowed[i] = l.Allow()
		}(i)
	}
	wg.Wait()
	count := 0
	for _, ok := range allowed {
		if ok {
			count++
		}
	}
	if count != 100 {
		t.Errorf("allowed %d requests, want exactly 100 (burst)", count)
	}
}
